const expected=$('30 labelled tickets').all(); const results=$input.all();
const details=expected.map((x,i)=>{const e=x.json;const a=results[i]?.json||{};const matched=a.ticket_id===e.ticket_id;const c=matched&&a.category===e.expected_category;const p=matched&&a.priority===e.expected_priority;const r=matched&&a.route===e.expected_route;return {ticket_id:e.ticket_id,message:e.message,expected_category:e.expected_category,actual_category:a.category||null,expected_priority:e.expected_priority,actual_priority:a.priority||null,expected_route:e.expected_route,actual_route:a.route||null,category_correct:c,priority_correct:p,route_correct:r,passed:c&&p&&r,status:a.status||'request_failed'};});
const pct=k=>Math.round(1000*details.filter(d=>d[k]).length/details.length)/10;
return [{json:{total:details.length,category_accuracy_percent:pct('category_correct'),priority_accuracy_percent:pct('priority_correct'),route_accuracy_percent:pct('route_correct'),all_fields_accuracy_percent:pct('passed'),manual_or_failed:details.filter(d=>d.status!=='queued').length,failures:details.filter(d=>!d.passed),details}}];
